ruff_python_index = { version = "0.0.21", path = "crates/ruff_python_index" }
ruff_python_literal = { version = "0.0.21", path = "crates/ruff_python_literal" }
ruff_python_parser = { version = "0.0.21", path = "crates/ruff_python_parser" }
ruff_python_semantic = { version = "0.0.21", path = "crates/ruff_python_semantic" }
ruff_python_stdlib = { version = "0.0.21", path = "crates/ruff_python_stdlib" }
ruff_python_trivia = { version = "0.0.21", path = "crates/ruff_python_trivia" }
ruff_server = { version = "0.0.21", path = "crates/ruff_server" }
ruff_source_file = { version = "0.0.21", path = "crates/ruff_source_file" }
ruff_mdtest = { path = "crates/ruff_mdtest" }
ruff_ranged_value = { version = "0.0.21", path = "crates/ruff_ranged_value" }
ruff_text_size = { version = "0.0.21", path = "crates/ruff_text_size" }
ruff_unicode_names2 = { version = "0.0.21", path = "crates/ruff_unicode_names2" }
ruff_unicode_names2_generator = { version = "0.0.21", path = "crates/ruff_unicode_names2_generator" }
ruff_workspace = { version = "0.0.21", path = "crates/ruff_workspace" }

ty = { path = "crates/ty" }
